\copy (WITH history_vehicles AS (SELECT DISTINCT vch.tenant_id, vch.vehicle_id FROM vehicle_cluster_history vch JOIN tenant_details td ON td.tenant_id = vch.tenant_id WHERE vch.week_start = '2026-11-02' AND td.tenant_drp = 5 AND (td.config->'VEHICLE_DRIVER_HISTORY'->>'enabled')::boolean IS TRUE) SELECT idet.image_id, idet.tenant_id, idet.vehicle_id, idet.face_s3_path FROM image_details idet JOIN history_vehicles hv ON hv.vehicle_id = idet.vehicle_id AND hv.tenant_id = idet.tenant_id WHERE idet.tenant_drp = 5 AND idet.timestamp >= '2026-11-09' AND idet.timestamp < '2026-11-16' AND random() < 0.0015 AND NOT EXISTS (SELECT 1 FROM arcface_prediction_details apd WHERE apd.tenant_drp = 5 AND apd.timestamp >= '2026-11-09' AND apd.timestamp < '2026-11-16' AND apd.image_id = idet.image_id AND apd.predicted_driver_id > 0) LIMIT 10000) TO '/Users/swapnilmane/NetraDyne/driver_history_use/data/AN-37740/step_1/an37740_sample_drp5.csv' WITH CSV HEADER;
